package com.vr3th.mediacompressor.engine
import android.content.Context;import android.graphics.Bitmap;import android.graphics.pdf.*;import android.net.Uri
import com.vr3th.mediacompressor.data.ProcessResult;import com.vr3th.mediacompressor.utils.StorageUtils;import java.io.FileOutputStream
class DocumentEngine(private val context:Context){
 fun compressPdf(uri:Uri,originalName:String,scaleFactor:Float=.75f):ProcessResult{val s=System.currentTimeMillis();var orig=0L;context.contentResolver.openFileDescriptor(uri,"r")?.use{orig=it.statSize};val out=StorageUtils.createTempFile(context,"pdf_",".pdf");val pfd=context.contentResolver.openFileDescriptor(uri,"r")?:throw IllegalArgumentException("Cannot open PDF file.");try{val r=PdfRenderer(pfd);val d=PdfDocument();val count=r.pageCount;for(i in 0 until count){val p=r.openPage(i);val w=(p.width*scaleFactor).toInt().coerceAtLeast(100);val h=(p.height*scaleFactor).toInt().coerceAtLeast(100);val b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);p.render(b,null,null,PdfRenderer.Page.RENDER_MODE_FOR_PRINT);p.close();val pi=PdfDocument.PageInfo.Builder(w,h,i+1).create();val np=d.startPage(pi);np.canvas.drawBitmap(b,0f,0f,null);d.finishPage(np);b.recycle()};FileOutputStream(out).use{d.writeTo(it)};d.close();r.close();pfd.close();return ProcessResult(true,originalName,orig,out.length(),"$count Pages","Optimized ($count Pages)",0,0,"PDF Standard","Compacted Native PDF",System.currentTimeMillis()-s,out.absolutePath)}catch(x:Exception){return ProcessResult(false,originalName,orig,0,"-","-",0,0,"-","-",0,"",errorMessage=x.localizedMessage?:"PDF compression failed")}}
}
